import uuid

def ingest(doc_uri: str, chunks: list[str], conn) -> None:
    for pos, text in enumerate(chunks):
        conn.execute(
            "INSERT INTO chunks (chunk_id, source_uri, position, text) "
            "VALUES (%s, %s, %s, %s) ON CONFLICT (chunk_id) DO NOTHING",
            (str(uuid.uuid4()), doc_uri, pos, text),
        )
